import urllib.request,json
s=json.load(urllib.request.urlopen('https://www.kernel.sh/openapi.json'))
for k,v in s['components']['schemas'].items():
 if ('Telemetry' in k or 'ManagedAuth' in k) and any(t in k for t in ('Config','Request','Event','Result','Browser')):
  print(k, json.dumps(v,separators=(',',':')))
print('PATHS')
for p,methods in s['paths'].items():
 if 'telemetry' in p or ('connections' in p and ('login' in p or 'events' in p)):
  print(p, json.dumps(methods,separators=(',',':'))[:12000])
